css:
.stage { position: relative; min-height: 215px; padding: 20px 14px 40px; border: 1px dashed #334155; border-radius: 6px; background: #0d1016; }
.card { position: relative; border: 2px solid #38bdf8; border-radius: 8px; padding: 12px; background: rgba(56, 189, 248, 0.08); width: 82%; }
#sandbox-root.contain-layout .card { contain: layout; border-color: #34d399; }
#sandbox-root.contain-paint .card { contain: paint; border-color: #f59e0b; }
#sandbox-root.contain-size .card { contain: size; border-color: #f87171; }
#sandbox-root.contain-layout.contain-paint .card { contain: layout paint; }
#sandbox-root.contain-layout.contain-size .card { contain: layout size; }
#sandbox-root.contain-paint.contain-size .card { contain: paint size; }
#sandbox-root.contain-layout.contain-paint.contain-size .card { contain: layout paint size; }
.overflow-badge { position: absolute; top: -14px; right: -16px; background: #fb923c; color: #090b0f; font-size: 11px; font-weight: 700; padding: 2px 7px; border-radius: 999px; }
.card-title { font-weight: 600; color: #f8fafc; margin-bottom: 4px; }
.card-body { margin: 0; font-size: 12px; color: #cbd5e1; }
.fixed-chip { position: fixed; right: 12px; bottom: 44px; background: #a78bfa; color: #090b0f; font-size: 11px; font-weight: 700; padding: 3px 8px; border-radius: 4px; }
.readout { position: absolute; left: 10px; right: 10px; bottom: 8px; font-size: 11px; color: #cbd5e1; background: #090b0f; border: 1px solid #1e293b; border-radius: 4px; padding: 5px 8px; }
